window.addEventListener('DOMContentLoaded', function(){
 const params=new URLSearchParams(location.search), id=params.get('id');
 const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
 const T=k=>window.LUMINA?.t?window.LUMINA.t(k):k;
 const paises=[['PT','Portugal'],['ES','Espanha'],['FR','França'],['DE','Alemanha'],['IT','Itália'],['NL','Países Baixos'],['BE','Bélgica'],['AT','Áustria'],['IE','Irlanda'],['SE','Suécia'],['DK','Dinamarca'],['FI','Finlândia'],['PL','Polónia'],['CZ','Chéquia'],['RO','Roménia'],['GB','Reino Unido'],['US','Estados Unidos'],['CA','Canadá'],['MX','México'],['BR','Brasil'],['CL','Chile'],['AR','Argentina'],['CO','Colômbia'],['AU','Austrália'],['NZ','Nova Zelândia'],['AO','Angola']];
 $('#pais-frete').innerHTML='<option value="">'+T('Selecione o país')+'</option>'+paises.map(p=>`<option value="${p[0]}">${p[1]}</option>`).join('');
 let produto=null,variante=null,quantidade=1;
 const stars=n=>{const v=Math.max(0,Math.min(5,Number(n)||0));return `<span class="stars" aria-label="${v} de 5">${[1,2,3,4,5].map(i=>`<svg viewBox="0 0 24 24" width="15" height="15" fill="${i<=Math.round(v)?'currentColor':'none'}" stroke="currentColor" stroke-width="1.5"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/></svg>`).join('')}</span>`};
 function atualizar(){if(!produto)return;const preco=Number(produto.precoAtualEUR??produto.precoVendaEUR??0)+Number(variante?.preco_extra_eur||0);$('#produto-preco').dataset.luminaEur=preco;const anterior=Number(produto.precoVendaEUR||0);const ehPromo=Number(produto.precoAtualEUR??anterior)<anterior;$('#produto-preco-anterior').hidden=!ehPromo;$('#produto-preco-anterior').dataset.luminaEur=anterior;$('#produto-preco-anterior').textContent=window.LUMINA?window.LUMINA.money(anterior):anterior.toLocaleString('pt-PT',{style:'currency',currency:'EUR'});$('#produto-preco').textContent=(window.LUMINA?window.LUMINA.money(preco):preco.toLocaleString('pt-PT',{style:'currency',currency:'EUR'}));const stock=Number(variante?.stock??produto.stockDisponivel??0);$('#stock-produto').innerHTML=stock>0?`<span class="stock-ok">${T('Disponível')}</span><span>${stock} ${T(stock===1?'unidade':'unidades')} ${T(stock===1?'registada':'registadas')}</span>`:`<span class="stock-off">${T('Indisponível')}</span>`;$('#botao-add-produto').disabled=stock<=0;$('#botao-add-produto').textContent=stock>0?T('Adicionar ao carrinho'):T('Indisponível');}
 function renderVars(vars){if(!Array.isArray(vars)||!vars.length){$('#bloco-variantes').hidden=true;return;}$('#bloco-variantes').hidden=false;const grupos={};vars.forEach(v=>(grupos[v.nome_opcao||'Opção']??=[]).push(v));const [nome,list]=Object.entries(grupos)[0];$('#nome-opcao-variante').textContent=nome;$('#opcoes-variacao').innerHTML=list.map((v,i)=>`<button type="button" class="opcao-variacao${i===0?' selecionada':''}" data-var="${v.id}">${esc(v.valor_opcao||v.nome||'Opção')}</button>`).join('');variante=list[0];$('#opcoes-variacao').querySelectorAll('button').forEach(b=>b.onclick=()=>{variante=list.find(v=>String(v.id)===b.dataset.var);$('#opcoes-variacao').querySelectorAll('button').forEach(x=>x.classList.remove('selecionada'));b.classList.add('selecionada');atualizar();calcularFrete();});}
 function renderGallery(){const imgs=produto.imagens||[];$('#galeria-principal').innerHTML=imgs[0]?`<img class="imagem-produto-real" src="${esc(imgs[0].url)}" alt="${esc(produto.nome)}">`:'<div class="produto-imagem-placeholder"></div>';$('#miniaturas').innerHTML=imgs.map((x,i)=>`<button class="miniatura-real${i===0?' ativa':''}" type="button"><img src="${esc(x.url)}" alt=""></button>`).join('');$('#miniaturas').querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{$('#galeria-principal').innerHTML=`<img class="imagem-produto-real" src="${esc(imgs[i].url)}" alt="${esc(produto.nome)}">`;$('#miniaturas').querySelectorAll('button').forEach(x=>x.classList.remove('ativa'));b.classList.add('ativa');});}
 async function carregarAvaliacoes(){try{const d=await apiFetch('/produtos/'+id+'/avaliacoes');const lista=[...(d.proprias?.lista||[])];const fornecedor=[];let html='';if(lista.length){html+=lista.map(a=>`<article class="avaliacao-item"><div class="avaliacao-topo"><strong>${esc(a.nome_autor)}</strong><time>${new Date(a.criado_em).toLocaleDateString('pt-PT')}</time></div><div>${stars(a.estrelas)}</div><p>${esc(a.comentario||'')}</p><small>${T('Avaliação de cliente Lúmina')}</small></article>`).join('');}$('#avaliacoes-lista').innerHTML=html||`<p>${T('Ainda não existem avaliações públicas para este produto.')}</p>`;if((d.proprias?.total||0)>0)$('#nota-avaliacoes').textContent=`${d.proprias.total} ${T(d.proprias.total===1?'avaliação':'avaliações')} ${T('de clientes Lúmina')}`; }catch(e){$('#avaliacoes-lista').innerHTML=`<p>${T('As avaliações não estão disponíveis neste momento.')}</p>`;}}
 function paisAutomatico(){const saved=String(localStorage.getItem('lumina_country')||'').toUpperCase();if(paises.some(p=>p[0]===saved))return saved;const nav=(navigator.language||'').toLowerCase();const mapa={'pt-pt':'PT','pt-br':'BR','en-us':'US','en-gb':'GB','en-ca':'CA','es-es':'ES','es-mx':'MX','fr-fr':'FR','de-de':'DE','it-it':'IT','nl-nl':'NL','pl-pl':'PL','sv-se':'SE','da-dk':'DK'};return mapa[nav]||({pt:'PT',en:'US',es:'ES',fr:'FR',de:'DE',it:'IT',nl:'NL',pl:'PL'}[nav.slice(0,2)]||'PT');}
 function moedaAtual(){return window.LUMINA?.currency?window.LUMINA.currency():(localStorage.getItem('lumina_currency')||'EUR');}
 function formatarFrete(m){const cur=moedaAtual();if(window.LUMINA?.money&&Number.isFinite(Number(m.custoEUR)))return window.LUMINA.money(Number(m.custoEUR));const n=Number(m.custoMoeda??m.custoUSD??0);return new Intl.NumberFormat(navigator.language||'pt-PT',{style:'currency',currency:cur,maximumFractionDigits:['CLP','COP','AOA'].includes(cur)?0:2}).format(n);}
 async function calcularFrete(){const pais=$('#pais-frete').value;if(!pais){$('#resultado-frete').innerHTML=`<p>${T('Não foi possível identificar o país de entrega.')}</p>`;return;}$('#frete-status').textContent='…';$('#destino-frete-label').textContent=$('#pais-frete').selectedOptions[0]?.textContent||pais;$('#resultado-frete').innerHTML=`<p>${T('A consultar todas as opções disponíveis…')}</p>`;try{const q=new URLSearchParams({pais,quantidade:String(quantidade),varianteId:String(variante?.id||0),moeda:moedaAtual()});if($('#zip-frete').value.trim())q.set('zip',$('#zip-frete').value.trim());const d=await apiFetch('/produtos/'+id+'/fretes?'+q);if(!d.metodos?.length){$('#frete-status').textContent=T('Indisponível');$('#resultado-frete').innerHTML=`<div class="frete-indisponivel"><strong>${T('Este produto não entrega neste país.')}</strong><span>${T('Não existe neste momento um método de envio disponível para o destino selecionado.')}</span></div>`;return;}$('#frete-status').textContent=`${d.metodos.length} ${T(d.metodos.length===1?'opção':'opções')}`;$('#resultado-frete').innerHTML=d.metodos.map((m,i)=>`<div class="opcao-frete"><span><strong>${esc(m.nome)}</strong><small>${m.prazo?`${T('Prazo estimado:')} ${esc(m.prazo)}`:T('Prazo não informado pelo fornecedor')}</small></span><b>${esc(formatarFrete(m))}</b></div>`).join('');}catch(e){$('#frete-status').textContent='—';$('#resultado-frete').innerHTML=`<p>${esc(e.message||'Não foi possível consultar a entrega neste momento.')}</p>`;}}
 async function carregar(){if(!id){$('#produto-nome').textContent=T('Produto indisponível');return;}try{produto=await apiFetch('/produtos/'+encodeURIComponent(id));document.title=produto.nome+' — Lúmina';const canon=document.querySelector('link[rel=canonical]');if(canon&&window.LUMINA_SITE_URL)canon.href=window.LUMINA_SITE_URL+'/produto.html?id='+encodeURIComponent(id);const descMeta=document.querySelector('meta[name=description]');if(descMeta)descMeta.content=String(produto.descricao||produto.nome).slice(0,250);const ld={'@context':'https://schema.org','@type':'Product',name:String(produto.nome||''),description:String(produto.descricao||''),image:/^https:\/\//i.test(String(produto.imagem_principal||''))?[produto.imagem_principal]:undefined,offers:{'@type':'Offer',price:Number(produto.precoAtualEUR??produto.precoVendaEUR??0).toFixed(2),priceCurrency:'EUR',availability:Number(produto.stockDisponivel||0)>0?'https://schema.org/InStock':'https://schema.org/OutOfStock',url:window.LUMINA_SITE_URL?window.LUMINA_SITE_URL+'/produto.html?id='+encodeURIComponent(id):location.href}};const ldTag=document.createElement('script');ldTag.type='application/ld+json';ldTag.textContent=JSON.stringify(ld);document.head.appendChild(ldTag);$('#migalha-produto').textContent=produto.nome;$('#produto-nome').textContent=produto.nome;$('#produto-categoria').textContent=produto.categoria||'Produto';$('#produto-descricao').textContent=produto.descricao||T('Informação do produto não disponível.');$('#produto-descricao-longa').innerHTML=esc(produto.descricao||'').replace(/\n/g,'<br>');renderGallery();renderVars(produto.variantes);atualizar();calcularFrete();$('#detalhes-produto').innerHTML=`<div><dt>${T('Peso')}</dt><dd>${produto.peso_gramas?esc(produto.peso_gramas)+' g':T('Não informado')}</dd></div>`;await carregarAvaliacoes();}catch(e){$('#produto-nome').textContent=T('Produto indisponível');$('#produto-descricao').textContent=e.message||'Este produto não está disponível neste momento.';}}
 window.addEventListener('lumina:currency-ready',()=>{atualizar();if(produto)calcularFrete();});
 window.addEventListener('lumina:currency-changed',()=>{atualizar();if(produto)calcularFrete();});
 $('#pais-frete').value=paisAutomatico();localStorage.setItem('lumina_country',$('#pais-frete').value);$('#pais-frete').addEventListener('change',()=>{localStorage.setItem('lumina_country',$('#pais-frete').value);calcularFrete();});$('#zip-frete').addEventListener('change',calcularFrete);
 $('#botao-favorito').onclick=async()=>{if(!produto)return;const token=obterTokenCliente();if(token){try{const atual=await apiFetch('/publico/favoritos');const existe=atual.some(x=>String(x.id)===String(produto.id));if(existe){await apiFetch('/publico/favoritos/'+produto.id,{method:'DELETE'});$('#botao-favorito').textContent='Guardar';}else{await apiFetch('/publico/favoritos/'+produto.id,{method:'POST'});$('#botao-favorito').textContent='Guardado';}}catch(e){$('#mensagem-produto').textContent=e.message;}}else{const ids=JSON.parse(localStorage.getItem('lumina_favoritos')||'[]').map(String);const i=ids.indexOf(String(produto.id));if(i>=0)ids.splice(i,1);else ids.push(String(produto.id));localStorage.setItem('lumina_favoritos',JSON.stringify(ids));$('#botao-favorito').textContent=i>=0?'Guardar':'Guardado';}};
 document.getElementById('form-avaliacao').addEventListener('submit',async e=>{e.preventDefault();const m=document.getElementById('avaliacao-msg'),b=e.currentTarget.querySelector('button');if(!obterTokenCliente()){m.textContent='Inicie sessão para enviar uma avaliação.';return;}m.textContent='A enviar...';b.disabled=true;try{await apiFetch('/produtos/'+encodeURIComponent(id)+'/avaliacoes',{method:'POST',body:JSON.stringify({estrelas:Number(document.getElementById('avaliacao-estrelas').value),comentario:document.getElementById('avaliacao-comentario').value})});m.textContent='Avaliação enviada para moderação.';e.currentTarget.reset();}catch(err){m.textContent=err.message;}finally{b.disabled=false;}});
 $('#botao-add-produto').onclick=()=>{if(!produto||!variante&&produto.variantes?.length)return;const preco=Number(produto.precoAtualEUR??produto.precoVendaEUR??0)+Number(variante?.preco_extra_eur||0);adicionarAoCarrinho(produto.id,produto.nome,preco,quantidade,{imagem:produto.imagem_principal||produto.imagens?.[0]?.url||null,varianteId:variante?.id||null,varianteNome:variante?(variante.valor_opcao||variante.nome||null):null,stock:Number(variante?.stock??produto.stockDisponivel??0)});$('#mensagem-produto').textContent=T('Produto adicionado ao carrinho.');};
 $('.diminuir').onclick=()=>{quantidade=Math.max(1,quantidade-1);$('#quantidade-produto').textContent=quantidade;calcularFrete();};$('.aumentar').onclick=()=>{quantidade=Math.max(1,Math.min(99,Number(variante?.stock??produto?.stockDisponivel??99)||1,quantidade+1));$('#quantidade-produto').textContent=quantidade;calcularFrete();};
 document.querySelectorAll('.botao-aba').forEach(b=>b.onclick=()=>{document.querySelectorAll('.botao-aba').forEach(x=>x.classList.remove('ativa'));document.querySelectorAll('.conteudo-aba').forEach(x=>x.classList.remove('ativa'));b.classList.add('ativa');document.querySelector(`.conteudo-aba[data-aba="${b.dataset.aba}"]`).classList.add('ativa');});
 async function carregarRelacionados(){try{const lista=await apiFetch('/produtos');const rel=lista.filter(p=>String(p.id)!==String(id)).slice(0,4);document.getElementById('produtos-relacionados').innerHTML=rel.map(p=>`<a href="produto.html?id=${p.id}" class="cartao-produto"><div class="imagem-produto">${p.imagem_principal?`<img src="${esc(p.imagem_principal)}" alt="" loading="lazy">`:''}</div><div class="info-produto"><div class="categoria-produto">${esc(p.categoria||'')}</div><h3>${esc(p.nome)}</h3><div class="preco" data-lumina-eur="${Number(p.precoAtualEUR??p.precoVendaEUR??0)}">${(window.LUMINA?window.LUMINA.money(Number(p.precoAtualEUR??p.precoVendaEUR??0)):Number(p.precoAtualEUR??p.precoVendaEUR??0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'}))}</div></div></a>`).join('');}catch(e){}}
 carregar();
 carregarRelacionados();
});
